/// Compares an LF-, CR-, or NUL-terminated identity token.
fn identity_token_eq(addr: usize, expected: &[u8]) -> bool {
    let mut i = 0usize;
    while i <= expected.len() && i < 64 {
        let b = unsafe { *((addr + i) as *const u8) };
        if i < expected.len() {
            if b != expected[i] { return false; }
        } else {
            return b == 0 || b == b'\n' || b == b'\r';
        }
        i += 1;
    }
    false
}

